WITH upsert_job AS (
INSERT INTO content_jobs (external_job_ref, project_name, brief_text, requested_outputs, drive_root_folder_id, status, created_by)
VALUES (NULLIF('{{$json.external_job_ref}}',''), COALESCE('{{$json.project_name}}','Untitled AI content job'), COALESCE('{{$json.brief_text}}',''), COALESCE(NULLIF('{{$json.requested_outputs_json || JSON.stringify($json.requested_outputs || [])}}',''),'[]')::jsonb, NULLIF('{{$json.drive_folder_id}}',''), 'intake_complete', COALESCE('{{$json.created_by}}','api_supervisor'))
ON CONFLICT (external_job_ref) DO UPDATE SET updated_at=now(), status='intake_complete', brief_text=EXCLUDED.brief_text RETURNING id, status
), msg AS (
INSERT INTO job_messages (job_id, sender_type, sender_id, message_type, message_text, attachments)
SELECT id, 'agent', COALESCE('{{$json.sender_id}}','supervisor'), 'brief', COALESCE('{{$json.message}}','{{$json.brief_text}}',''), '[]'::jsonb FROM upsert_job RETURNING id
), event AS (
INSERT INTO content_events (job_id, event_type, message, metadata) SELECT id, 'intake_complete', 'Job intake completed', jsonb_build_object('operator_architecture','v2','dry_run',COALESCE('{{$json.mode}}','dry_run')) FROM upsert_job RETURNING id)
SELECT id::text AS job_id, status::text AS status FROM upsert_job;

